import {usbOptions} from './usb-core.js';
import {esc,btn,field,select,icon} from './views.js';
import {profileFor} from './slicer-core.js';
import {formatTime,parseGcode} from './core.js';
export function slicerPage(s,u){const p=s.printers.find(p=>p.id===s.activePrinterId),c=profileFor(p),b=s.boxes.find(b=>b.id===u.selected)||s.boxes.find(b=>!b.archived),o=b?.objects.find(o=>o.id===u.objectId)||b?.objects[0],stats=u.sliceText?parseGcode(u.sliceText,{diameter:p.diameter,density:p.density}):null;
 const number=(label,k,min=0,max=1000)=>field(label,c[k],`data-slice-setting="${k}" min="${min}" max="${max}"`);
 return `<div class="page-heading"><div><div class="eyebrow">MODELO → CAPAS → IMPRESORA</div><h1>Del bosque a la cama.</h1><p>Laminador local con CuraEngine · ${esc(p.printer)}</p></div><div class="heading-actions">${o?.lastSliceFile?btn('Último laminado','slice-load-last','file'):''}${btn('Abrir G-code','slice-import','upload')}${btn('Laminar esta cama','slice-run','layers','primary',u.sliceRunning?'disabled':'')}</div></div>
 <div class="slicer-layout"><div class="stack"><div class="panel"><div class="form-grid">${select('Impresora',s.printers.map(p=>[p.id,p.printer]),s.activePrinterId,'id="slice-printer"')}${select('Caja',s.boxes.filter(b=>!b.archived).map(b=>[b.id,b.name]),b?.id,'id="slice-box"')}${select('Objeto',(b?.objects||[]).map(o=>[o.id,o.name]),o?.id,'id="slice-object"')}${select('Contenido de la cama',[['all','Todos sus componentes'],...(o?.parts||[]).map(p=>[p.id,p.name])],u.slicePart||'all','id="slice-part"')}${field('Repeticiones del objeto / pieza',u.sliceCopies||1,'id="slice-copies" min="1" max="100" step="1"')}</div><p class="short-note">Se acomoda una cama con separación entre cajas envolventes. Si no cabe, reduce las repeticiones o lamina componentes por separado. El montaje de la portada se conserva.</p></div>
 <div class="viewer workspace-viewer" id="slice-viewer"></div><div class="flex">${btn('Ver modelos en la cama','slice-models','box','small')}${btn('Ver recorridos de impresión','slice-paths','layers','small',u.sliceText?'':'disabled')}${btn('Encuadrar','slice-fit','expand','small')}</div>
 ${u.sliceText?`<div class="panel"><div class="between"><h3>${esc(u.sliceName||'G-code preparado')}</h3><span class="badge">${stats?.valid?formatTime(stats.minutes):'Tiempo no informado'}</span></div><div class="mini-stats"><div><b>${stats?.valid?formatTime(stats.minutes):'—'}</b><span>Tiempo total de esta cama</span></div><div><b>${u.sliceStats?u.sliceStats.grams.toFixed(2):stats?.grams?.length?stats.grams.reduce((a,b)=>a+b,0).toFixed(2):'—'} g</b><span>Filamento total${u.sliceStats?' · calculadora actualizada':''}</span></div></div><div class="form-grid section-space">${field('Hasta la capa',u.sliceLayer||1,`id="slice-layer" min="1" max="${u.sliceAnalysis?.maxLayer||1}" step="1"`)}<label class="field">Recorrer capas<input id="slice-layer-range" type="range" min="1" max="${u.sliceAnalysis?.maxLayer||1}" value="${u.sliceLayer||1}"></label></div><p class="short-note">Colores: herramientas · líneas tenues: desplazamientos. Capas detectadas: ${u.sliceAnalysis?.maxLayer||0}. Vista de trayectorias, sin simular colisiones ni ancho real de extrusión.</p>${(u.sliceAnalysis?.warnings||[]).map(w=>`<p class="danger-text small">${esc(w)}</p>`).join('')}<div class="flex section-space">${btn('Guardar G-code','slice-export','download','small')}${btn('Aplicar a la calculadora','slice-estimates','calculator','small')}</div></div>`:''}
 <div class="panel"><h3>Cambios de color por capa</h3><p class="short-note">La capa 1 es la primera capa del modelo (no incluye raft). El cambio se ejecuta antes de esa capa. Para pintar colores dentro de la misma capa, asigna herramientas a mallas separadas.</p><div class="form-grid section-space">${field('Antes de la capa',2,'id="color-layer" min="1" step="1"')}${select('Método',[['host','Pausa USB de 3D-Woods (estacionar y continuar)'],['M600','M600 · cambio gestionado por firmware'],['M0','M0 · pausa confirmada en la impresora'],['tool','Automático · herramienta / alimentador Tn']],'host','id="color-mode"')}${field('Herramienta automática (desde 0)',1,`id="color-tool" min="0" max="${c.tools-1}" step="1"`)}</div><div class="section-space">${btn('Agregar cambio','add-color-change','plus','small',u.sliceText?'':'disabled')}</div><div class="section-space">${(o?.colorChanges||u.colorChanges||[]).map((x,i)=>`<div class="between cost-row"><span>Capa ${x.layer} · ${x.mode==='host'?'Pausa USB':esc(x.mode)}${x.mode==='tool'?' T'+x.tool:''}</span>${btn('Quitar','remove-color-change','trash','small',`data-index="${i}"`)}</div>`).join('')}</div><p class="short-note">Las pausas y purgas añadidas no recalculan el consumo ni el tiempo del encabezado: revisa el reparto por color en la calculadora. M600 y M0 requieren soporte del firmware. La pausa USB mantiene la temperatura y requiere continuar aquí; para exportar a SD elige una pausa de firmware. Tn solo funciona con hardware compatible: no añade cambio automático a una impresora de un solo filamento.</p></div>
 <div class="panel usb-panel"><div class="section-header"><h3>Imprimir por USB</h3><span class="badge outline">Marlin compatible</span></div><div class="form-grid">${select('Puerto de la impresora',usbOptions(u.devices||[],p),p.usbManual?'__manual__':p.deviceId||'','id="slice-device"')}${p.usbManual?field('Puerto COM de Windows',p.usbPort||'','id="usb-manual-port" placeholder="COM3"','text'):''}${select('Velocidad del puerto',[[115200,'115200'],[250000,'250000'],[230400,'230400'],[57600,'57600']],c.baud,'data-slice-setting="baud"')}</div><div class="flex section-space">${btn('Actualizar puertos','probe-printers','refresh','small')}${btn('Probar conexión','test-usb','printer','small')}${btn('Revisar e imprimir','slice-print','printer','primary')}</div><p class="short-note">${u.sliceText?'1 · G-code preparado.':'1 · Lamina esta cama o abre un G-code.'} 2 · Selecciona el puerto y los baudios. 3 · Prueba la conexión o revisa e imprime.</p><p id="usb-error" class="usb-error" ${u.printError?'':'hidden'}>${esc(u.printError||'')}</p><div id="print-monitor"><p data-print-status class="section-space">${esc(u.printStatus?.message||'Sin impresión activa')}</p><progress data-print-progress max="100" value="0"></progress></div><div class="flex section-space">${btn('Pausar envío','usb-pause','clock','small')}${btn('Continuar','usb-resume','arrow','small')}${btn('Detener · M112','usb-stop','close','danger small')}</div><details class="section-space"><summary>Diagnóstico USB</summary><pre id="usb-log" class="slice-log">${esc((u.printError?u.printError+'\n':'')+(u.printStatus?.log||'El intercambio USB aparecerá aquí.'))}</pre>${btn('Guardar diagnóstico','export-usb-diagnostic','download','small')}</details><p class="short-note">Probar conexión abre el puerto y consulta M115, sin mover ni calentar. Puede reiniciar la placa. Cierra otros programas que usen ese puerto. La pausa de envío se aplica tras el comando actual y no estaciona el cabezal. Los cambios de color programados sí lo estacionan. Detener solicita M112; puede ser necesario reiniciar la impresora. No cierres la app ni desconectes el USB mientras imprime.</p></div></div>
 <aside class="stack"><div class="panel"><h3>Ajustes de laminado</h3><div class="form-grid section-space">${number('Capa (mm)','layer',.05,1)}${number('Primera capa (mm)','firstLayer',.05,1)}${number('Boquilla (mm)','nozzle',.1,2)}${number('Paredes','walls',0,100)}${number('Capas superiores','topLayers',0,100)}${number('Capas inferiores','bottomLayers',0,100)}${number('Relleno (%)','infill',0,100)}${select('Patrón',[['grid','Cuadrícula'],['lines','Líneas'],['triangles','Triángulos'],['cubic','Cúbico'],['gyroid','Giroide']],c.pattern,'data-slice-setting="pattern"')}${number('Impresión (mm/s)','speed',1,500)}${number('Viajes (mm/s)','travel',1,500)}${number('Boquilla (°C)','temperature',0,350)}${number('Cama (°C)','bedTemperature',0,150)}${number('Retracción (mm)','retract',0,30)}${number('Retracción (mm/s)','retractSpeed',1,150)}${number('Ventilador (%)','fan',0,100)}${number('Ángulo de soporte (°)','supportAngle',0,90)}${select('Adhesión',[['none','Ninguna'],['skirt','Falda'],['brim','Borde'],['raft','Balsa']],c.adhesion,'data-slice-setting="adhesion"')}${number('Borde (mm)','brim',0,30)}</div><label class="field inline section-space"><input type="checkbox" data-slice-setting="support" ${c.support?'checked':''}> Generar soportes desde la cama</label><p class="short-note">Valores iniciales orientativos para PLA. Ajusta el perfil según tu boquilla, material e impresora. Los cambios necesitan volver a laminar; no modifican el G-code ya preparado.</p></div>
 <div class="panel"><h3>Orientación y herramientas</h3><div class="form-grid section-space">${number('Cantidad de herramientas','tools',1,8)}<label class="field inline"><input type="checkbox" data-slice-setting="autoTools" ${c.autoTools?'checked':''}> Mi equipo y perfil admiten T0/T1…</label></div>${(o?.parts||[]).map(part=>`<div class="section-space"><b class="small">${esc(part.name)}</b><div class="coords">${['X','Y','Z'].map((axis,i)=>field(`Giro ${axis} (°)`,o.sliceRotations?.[part.id]?.[i]||0,`data-slice-rotation="${esc(part.id)}" data-axis="${i}" min="-360" max="360"`)).join('')}</div>${select('Herramienta',Array.from({length:c.tools},(_,i)=>[i,`T${i}`]),o.toolAssignments?.[part.id]||0,`data-slice-tool="${esc(part.id)}"`)}</div>`).join('')}${Array.from({length:c.tools},(_,i)=>select(`Filamento físico de T${i}`,[['','Selecciona filamento'],...s.materials.filter(m=>!m.retired).map(m=>[m.id,m.name])],c.materials?.[i]||o?.parts.find(p=>(o.toolAssignments?.[p.id]||0)===i)?.matId||'',`data-tool-material="${i}"`)).join('')}<p class="short-note">Cada herramienta usa el filamento elegido. Para colores distintos con una sola herramienta, programa pausas y ajusta el reparto por color en la calculadora. Estas rotaciones se aplican solo a la cama de impresión. Mallas con herramientas diferentes se distribuyen como piezas separadas; no es pintura multicolor.</p></div>
 <details class="panel"><summary>Motor local y opciones avanzadas</summary><p class="short-note">Motor CuraEngine 5.13.0 incluido. Lamina en tu equipo sin instalar otra aplicación ni conectarse a internet.</p>${select('Motor',[['builtin','Incluido · CuraEngine 5.13.0'],['custom','Personalizado · otra versión local']],s.settings.engineMode||'builtin','id="engine-mode"')}<div class="section-space">${btn(s.settings.engineMode==='custom'?'Detectar motor personalizado':'Comprobar motor incluido','detect-engine','refresh','small')}${s.settings.engineMode==='custom'?btn('Seleccionar motor','pick-engine','folder','small'):''}</div>${s.settings.engineMode==='custom'?field('Ruta de CuraEngine',s.settings.enginePath||'','data-engine-path="enginePath"','text')+field('fdmprinter.def.json',s.settings.engineDefinition||'','data-engine-path="engineDefinition"','text')+field('fdmextruder.def.json',s.settings.extruderDefinition||'','data-engine-path="extruderDefinition"','text'):''}<label class="field section-space">G-code inicial<textarea rows="7" data-slice-setting="start">${esc(c.start)}</textarea></label><label class="field section-space">G-code final<textarea rows="5" data-slice-setting="end">${esc(c.end)}</textarea></label><label class="field section-space">Cambio automático · {tool} se sustituye por su número<textarea rows="3" data-slice-setting="toolChange">${esc(c.toolChange)}</textarea></label><label class="field section-space">Opciones resueltas de CuraEngine (JSON)<textarea rows="10" data-slice-setting="advanced" spellcheck="false">${esc(c.advanced)}</textarea></label><p class="short-note">Formato: {"global":{"clave":valor},"extruders":[{"clave":valor}]}. Admite claves del motor local. Introduce valores concretos: las fórmulas Python de perfiles de Cura no se evalúan aquí. Las opciones avanzadas tienen prioridad sobre los controles simples.</p>${btn('Consultar claves del motor','engine-keys','list','small')}<p class="short-note">Esta edición no replica pintura, modificadores, soportes pintados ni todos los complementos de Cura. Para esos trabajos puedes preparar el G-code en Cura y cargarlo aquí.</p></details>
 <div class="panel"><div class="between"><h3>Proceso de laminado</h3>${btn('Cancelar','slice-cancel','close','small')}</div><p id="slice-job-status">${u.sliceRunning?'Laminando…':'Sin proceso activo'}</p><pre id="slice-log" class="slice-log">${esc(u.sliceLog||'El registro del motor aparecerá aquí.')}</pre></div></aside></div>`;
}
